// Carry all project data forward after marking as Processing
const project = $('Query Unsynced Projects').item.json;
return [{ json: project }];

// Find matching Asana project by ProjectName (exact match — per spec)
const projectData = $('Pass Project Context').item.json;
const portfolioItems = $input.item.json?.data ?? [];

const match = portfolioItems.find(
  p => (p.name || '').trim().toLowerCase() === (projectData.ProjectName || '').trim().toLowerCase()
);

return [{
  json: {
    ...projectData,
    asana_project_gid: match?.gid ?? null,
    asana_project_found: !!match
  }
}];

// Build custom_fields payload for Asana project update
// Maps SQL columns to Asana custom field GIDs
// Replace GID placeholders with actual GIDs from your Asana workspace

const project = $('Match Project by Name').item.json;
const asanaProject = $input.item.json?.data ?? {};

// Build a map of field name → GID from the live project
const fieldMap = {};
(asanaProject.custom_fields || []).forEach(f => {
  fieldMap[f.name] = f.gid;
});

// Helper: format date to YYYY-MM-DD, return null if blank
const fmtDate = (val) => {
  if (!val) return null;
  try { return new Date(val).toISOString().split('T')[0]; } catch { return null; }
};

// Helper: format numeric — return null if blank (spec requires NULL support)
const fmtNum = (val) => (val === null || val === undefined || val === '') ? null : parseFloat(val);

// Build custom_fields update object
// Key = Asana custom field GID, Value = new value
// Uses fieldMap from live project — falls back to env var GIDs if needed
const customFields = {};

const addField = (fieldName, value) => {
  const gid = fieldMap[fieldName];
  if (gid && value !== null) customFields[gid] = value;
  else if (gid && value === null) customFields[gid] = null; // explicit null clears field
};

addField('Project Manager', project.ProjectManager ?? null);
addField('Actual Margin', fmtNum(project.SAPActualMargin));
addField('Revenue', fmtNum(project.Revenue));
addField('Open Revenue', fmtNum(project.OpenRevenue));
addField('Invoiced', fmtNum(project.PcttoInvoice));
addField('Full Contract Cost', fmtNum(project.TotalTateContractCost));
addField('First Onsite Date', fmtDate(project.FirstOnsiteDate));
addField('Last Onsite Date', fmtDate(project.LastOnsiteDate));

return [{
  json: {
    ...project,
    asana_project_gid: asanaProject.gid,
    custom_fields_payload: customFields
  }
}];

// Catch errors from Asana API call and log them to SQL
const project = $('Build Custom Fields Payload').item.json;
const error = $input.item.json;
return [{
  json: {
    ID: project.ID,
    error_message: error?.message || JSON.stringify(error).slice(0, 500)
  }
}];
